 "content": "from collections import deque

def transform(grid):
    """Recolor the object in the open lower-left sector of the long L marker."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            pts = []
            while q:
                y, x = q.pop()
                pts.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == col:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((col, pts))

    marker = None
    for col, pts in comps:
        ys = [y for y,x in pts]; xs = [x for y,x in pts]
        top, bottom, left, right = min(ys), max(ys), min(xs), max(xs)
        # A long, one-cell-thick L with arms meeting at a corner.
        if len(pts) >= 7 and (bottom-top+1) >= 5 and (right-left+1) >= 4:
            if len(pts) <= (bottom-top+1) + (right-left+1) - 1:
                marker = (col, pts, top, bottom, left, right)
                break
    if marker is None:
        return [row[:] for row in grid]

    mc, mpts, top, bottom, left, right = marker
    # Find the elbow and horizontal arm direction.
    if (bottom, left) in mpts:
        elbow = (bottom, left); arm_dir = -1
    elif (bottom, right) in mpts:
        elbow = (bottom, right); arm_dir = 1
    elif (top, left) in mpts:
        elbow = (top, left); arm_dir = -1
    else:
        elbow = (top, right); arm_dir = 1
    ey, ex = elbow

    # In the common downward-pointing marker, choose the nearest object in
    # the open sector below and left of its vertical stem.
    candidates = []
    for col, pts in comps:
        if col == mc:
            continue
        ys = [y for y,x in pts]; xs = [x for y,x in pts]
        cy = sum(ys) / len(ys); cx = sum(xs) / len(xs)
        if cx < ex and cy >= ey and (cy, cx) != (ey, ex):
            # Prefer the object directly below the elbow, then the one nearest it.
            d = min(abs(y-ey) + abs(x-ex) for y,x in pts)
            candidates.append((d, abs(cy-ey), -len(pts), col, pts))
    if not candidates:
        # Fallback to nearest component left of the upright arm.
        for col, pts in comps:
            if col == mc:
                continue
            if min(x for y,x in pts) < ex:
                d = min(abs(y-ey) + abs(x-ex) for y,x in pts)
                candidates.append((d, 0, -len(pts), col, pts))
    if not candidates:
        return [row[:] for row in grid]
    _, _, _, target_color, target_pts = min(candidates, key=lambda z: (z[0], z[1], z[2]))
    out = [row[:] for row in grid]
    for y,x in target_pts:
        out[y][x] = mc
    return out
